module.exports = function(data) {
    // 1. Zugriff auf die Datenbank-Daten (explizit über den Key 'db')
    // Wir fangen ab, falls es ein Array oder ein Objekt ist.
    var raw = data.db;
    if (Array.isArray(raw)) raw = raw[0];

    // Wenn keine Daten da sind, werfen wir einen Fehler, den man im Log sieht
    if (!raw) throw new Error("Keine Daten im Block 'db' gefunden!");

    // 2. Hilfsfunktion: Preise sicher in Strings wandeln (Pretix verlangt Strings wie "20.00")
    function formatPrice(val) {
        if (!val) return "0.00";
        var num = parseFloat(val);
        return isNaN(num) ? "0.00" : num.toFixed(2);
    }

    // 3. URLs vorbereiten (Damit wir kein {{undefined}} in der URL haben)
    var eventSlug = raw.slug;
    var baseUrl = "https://pretix.eu/api/v1/organizers/diebruecke/events/";

    // URL für das Event selbst
    var url_event = baseUrl; 
    // URL für Items (Tickets)
    var url_items = baseUrl + eventSlug + "/items/";
    // URL für Quotas (Kapazität)
    var url_quotas = baseUrl + eventSlug + "/quotas/";

    // 4. Bodys vorbereiten (JSON Strings)

    // Body: Event erstellen
    var json_event = JSON.stringify({
        name: { de: raw.title },
        slug: raw.slug,
        live: false,
        currency: "EUR",
        date_from: raw.start_date,
        date_to: raw.end_date,
        location: raw.location,
        plugins: ["pretix.plugins.ticketoutputpdf", "pretix.plugins.sendmail"]
    });

    // Body: Ticket Normal
    var json_ticket1 = JSON.stringify({
        name: { de: "Normalpreis" },
        default_price: formatPrice(raw.price_regular),
        admission: true, active: true, tax_rate: "0.00"
    });

    // Body: Ticket Ermäßigt
    var json_ticket2 = JSON.stringify({
        name: { de: "Ermäßigt" },
        default_price: formatPrice(raw.price_reduced),
        admission: true, active: true, tax_rate: "0.00"
    });

    // Body: Ticket Mitglied
    var json_ticket3 = JSON.stringify({
        name: { de: "Mitglied" },
        default_price: formatPrice(raw.price_member),
        admission: true, active: true, tax_rate: "0.00"
    });

    // Rückgabe an Directus
    return {
        slug: eventSlug,
        quota_size: parseInt(raw.capacity_total) || 0,

        // URLs
        url_event: url_event,
        url_items: url_items,
        url_quotas: url_quotas,

        // Payloads
        payload_event: json_event,
        payload_ticket1: json_ticket1,
        payload_ticket2: json_ticket2,
        payload_ticket3: json_ticket3
    };
};
